local function Call(cmd, ...)
  local r = table.pack(pcall(funcLuaCommand, cmd, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function Int(v)
  if type(v) ~= "number" then
    return 0
  end
  return math.floor(v + 0.5)
end

--- Advanced: Namespace: mouse pointer tracker for menus; holds new().
VRFW.pointer = VRFW.pointer or {}
--- Advanced: Creates a mouse pointer tracker; answers a table with zone setters (rect, box, inst), position, at, poll and reset.
VRFW.pointer.new = VRFW.pointer.new or function()
  local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
  local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
  local LEFT, CLICK = 749879980 --[[CMD_VRFW_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
  local W_UP, W_DOWN = 2649361876 --[[CMD_VRFW_WHEEL_UP]], 1098743808 --[[CMD_VRFW_WHEEL_DOWN]]
  local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
  local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
  local function M(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function In(cmd, ctrl)
    local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
    return ok and r == true
  end
  local function Edge(cmd, ctrl)
    local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
    local now = In(cmd, ctrl)
    local was = P.prev[key]
    P.prev[key] = now
    return now and not was
  end
  --- Starts a new list of pointer zones for this frame.
  function P.begin()
    P.zones = {}
  end
  --- Adds a zone by top-left corner and size; `id` is what P.at answers, `edge` as in P.poll.
  function P.rect(x, y, w, h, id, edge)
    P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
  end
  --- Adds a zone by centre and half sizes; `id` and `edge` as in P.rect.
  function P.box(cx, cy, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
  end
  --- Adds a zone that follows instance idx of a layer, with half sizes hw and hh.
  function P.inst(layer, idx, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
  end
  --- The pointer position: x, y, or nil when it is not available.
  function P.position()
    local x, y = M(POS)
    if type(x) == "number" and type(y) == "number" then return x, y end
    return nil
  end
  --- The topmost zone under (x, y), or under the last pointer position; nil when there is none.
  function P.at(x, y)
    if x == nil then x, y = P.x, P.y end
    if x == nil then return nil end
    for i = #P.zones, 1, -1 do
      local z = P.zones[i]
      if z.layer ~= nil then
        local gx, gy = M(GPOS, z.layer, z.idx)
        if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
          return z
        end
      elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
        return z
      end
    end
    return nil
  end
  -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
  --- True when this press belongs to the pointer: a left click, or a click over a zone while the pointer is on.
  function P.owns()
    return In(LEFT) or (P.on and In(CLICK) and P.at() ~= nil)
  end
  --- Clears the hovered zone.
  function P.forget()
    P.hot = nil
  end
  --- Hands the cursor to the keys for this frame: pointer off, hover cleared, position remembered.
  function P.key_step()
    P.on, P.hot = false, nil
    local x, y = P.position()
    if x ~= nil then P.x, P.y = x, y end
  end
  --- Clears the zones, the hover and the edge state, and remembers the pointer position.
  function P.reset()
    P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
    P.x, P.y = P.position()
    for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do Edge(c, ctrl) end
    end
  end
  --- One frame of pointer input; answers this frame's event table.
  function P.poll()
    local ev = {}
    local x, y = P.position()
    if x ~= nil then
      local moved = M(MOVED) == true
      if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
        moved = true
      end
      P.x, P.y = x, y
      if moved then
        P.on, ev.moved = true, true
      end
    end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do
        if Edge(c, ctrl) then
          ev.keys = true
        end
      end
    end
    if ev.keys and not ev.moved then
      P.on = false
    end
    local left, click = Edge(LEFT), Edge(CLICK)
    if left then
      P.on, ev.left = true, true
    end
    local z = P.on and P.at() or nil
    local id = z and z.id or nil
    ev.changed = id ~= P.hot
    P.hot, ev.hot = id, id
    if z ~= nil and (ev.moved or left) then
      ev.hover = id
    end
    if left then
      if z ~= nil then
        ev.click = id
      else
        ev.miss = true                 -- a mouse click on empty space: nothing
      end
    elseif click and P.on then
      if z ~= nil then
        ev.click = id
      else
        P.on, P.hot = false, nil
      end
    end
    if In(W_DOWN) then
      ev.wheel = 1
    elseif In(W_UP) then
      ev.wheel = -1
    end
    if z ~= nil and z.edge ~= nil then
      P.edge_t = P.edge_t - 1
      if P.edge_t <= 0 then
        ev.edge, P.edge_t = z.edge, P.REPEAT
      end
    else
      P.edge_t = 0
    end
    return ev
  end
  return P
end
local Kit, Ptr                  -- set in OnInit

local function Pages()
  return math.max(1, #B.pages)
end

local function Shown(p)
  if Pages() == 1 then
    return p == 0 and 1 or nil
  end
  if p == view then
    return 1
  elseif p == view + 1 then
    return 2
  end
  return nil
end

local function OnScreen()
  return Pages() == 1 and 1 or 2
end

-- the left edge of the k-th page on screen (1 / 2)
local function PageLeft(k)
  local n = OnScreen()
  local w = (n * B.cols + (n - 1) * G.GAP) * cell
  return G.CX - w / 2 + (k - 1) * (B.cols + G.GAP) * cell
end

local function HexLayout()
  cell = math.min(G.BOARD_W / ((B.cols - 1) * G.HEX_DX + 1), G.GRID_H / (B.rows + 0.5), G.CELL_MAX)
  local left = G.CX - (B.cols - 1) * G.HEX_DX * cell / 2
  local n = 0
  for t, tile in ipairs(B.tiles) do
    if Shown(tile.page) ~= nil and n < N.TILE then
      pos[t] = {left + tile.col * G.HEX_DX * cell, G.GRID_CY + (tile.row + (tile.col % 2) * 0.5 - B.rows / 2 + 0.25) * cell}
      slot_of[t] = n
      n = n + 1
    end
  end
end

local function Layout()
  pos, slot_of = {}, {}
  if B.layout == "hex" then
    return HexLayout()
  end
  local ns = OnScreen()
  cell = math.min(G.BOARD_W / (ns * B.cols + (ns - 1) * G.GAP), G.GRID_H / B.rows, G.CELL_MAX)
  local n = 0
  for t, tile in ipairs(B.tiles) do
    local k = Shown(tile.page)
    if k ~= nil and n < N.TILE then
      pos[t] = {PageLeft(k) + (tile.col + 0.5) * cell, G.GRID_CY + (tile.row - (B.rows - 1) / 2) * cell}
      slot_of[t] = n
      n = n + 1
    end
  end
end

-- Draws the background.
local function DrawBackground()
  local a = VRFW.screen_art.role(ART_SCREEN, "background")
  local tc = a ~= nil and Kit.texture(a.atlas) or nil
  if tc then
    Kit.textured_quad(L_BACK, 0, tc, a.crc, G.CX, 540, 1920, 1080)
  else
    Kit.hide_off_screen(L_BACK, 0)
  end
  funcLuaMenuCommand(C.LAYER_VISIBLE, L_RETAIL_BG, 0, a == nil or tc == nil)
end

local function Emblem(tile)
  if tile.emblem == "" then
    return nil
  end
  local tc = Kit.texture(EMB_DIR .. tile.emblem .. "_s.g4tx")
  if not tc then
    return tc                     -- false: still loading; nil: never came in (the "?" icon)
  end
  return tc, CRC32(tile.emblem .. "_s01")
end

local function RankBadge(layer, idx, rdef, x, y, size)
  local tc = nil
  if rdef ~= nil and rdef.badge ~= "" and rdef.atlas ~= "" then
    tc = Kit.texture(rdef.atlas)
  end
  if tc then
    Kit.textured_quad(layer, idx, tc, CRC32(rdef.badge), x, y, size, size)
  else
    Kit.hide_off_screen(layer, idx)
  end
end

-- Returns a double chest's icon.
local function DChestIcon(t)
  local st = VRFW.chain.tile_state(B, t)
  if VRFW.chain.d_chest_empty(B, t) then
    return "icon_chest_locked"
  elseif st == "o" then
    return "icon_chest_open"
  elseif st == "h" or st == "a" then
    return VRFW.chain.d_chest_ready(B, t) and "icon_schest" or "icon_schest_locked"
  end
  return VRFW.chain.open(B, t) and "icon_chest" or "icon_chest_locked"
end

local function DrawTile(t)
  local tile, p, s = B.tiles[t], pos[t], slot_of[t]
  local x, y = p[1], p[2]
  local ts, ic, bd = cell * G.TILE, cell * G.ICON, cell * G.BADGE
  local open = VRFW.chain.open(B, t)
  local st = VRFW.chain.tile_state(B, t)
  local plate, icon
  if tile.kind == "start" then
    plate, icon = "tile_start", "icon_start"
  elseif tile.kind == "slot" then
    plate, icon = "tile_hidden", false   -- a placeholder (no team yet): always the "?" plate
  elseif tile.kind == "blocked" then
    -- Uses the 3DS "prohibited" sign on the chests' lavender plate.
    plate = "tile_chest"
    icon = st ~= "0" and "icon_unblocked" or "icon_blocked"
  elseif tile.kind == "chest" or tile.kind == "schest" then
    -- A chest shows what it is from the start (IE3).
    local pre = tile.kind == "schest" and "icon_schest" or "icon_chest"
    plate = "tile_chest"
    icon = st == "o" and pre .. "_open" or (open and pre or pre .. "_locked")
  elseif tile.kind == "dchest" then
    -- Handles a double chest.
    plate = "tile_chest"
    icon = DChestIcon(t)
  elseif not open then
    plate, icon = "tile_hidden", false   -- a match not open yet: the "?" plate, no crest (IE3)
  else
    plate = st ~= "0" and "tile_done" or "tile_open"
  end
  Kit.art_quad(L_TILE, s, plate, x, y, ts, ts)
  Kit.colour(L_TILE, s, COLOUR.WHITE)   -- a hub's list tints its rows (the same pool)
  if icon == false then
    Kit.hide_off_screen(L_EMB, s)
  elseif icon == nil then
    local tc, sc = Emblem(tile)
    if tc == false then
      Kit.hide_off_screen(L_EMB, s)              -- still loading: Step draws it
    elseif tc == nil then
      Kit.art_quad(L_EMB, s, "icon_unknown", x, y, ic, ic)
    else
      Kit.textured_quad(L_EMB, s, tc, sc, x, y, ic, ic)
    end
  else
    local ics = (tile.kind == "chest" or tile.kind == "schest" or tile.kind == "dchest" or tile.kind == "blocked") and ts * G.CHEST or ic   -- chests / signs fill their plate
    Kit.art_quad(L_EMB, s, icon, x, y, ics, ics)
  end
  local rid = tile.kind == "match" and VRFW.chain.rank_id(B, t) or nil
  local rdef = rid ~= nil and VRFW.match_rank ~= nil and VRFW.match_rank.by_id(rid) or nil
  RankBadge(L_TAG, s, rdef, x + ts * 0.33, y + ts * 0.33, bd)
end

local function LinkColour(a, b)
  if VRFW.chain.done(B, a) and VRFW.chain.done(B, b) then
    return COLOUR.DONE
  elseif VRFW.chain.open(B, a) and VRFW.chain.open(B, b) then
    return COLOUR.OPEN
  end
  return COLOUR.LOCKED
end

local function Bar(li, x1, x2, y1, y2, c)
  if li >= N.LINE then
    return li
  end
  funcLuaMenuCommand(C.ROTATE, L_LINE, 0, 0, 0, li)
  if math.abs(y1 - y2) < 1 then
    Kit.art_quad(L_LINE, li, "line", (x1 + x2) / 2, y1, math.abs(x2 - x1), G.LINE)
  else
    Kit.art_quad(L_LINE, li, "line", x1, (y1 + y2) / 2, G.LINE, math.abs(y2 - y1))
  end
  Kit.colour(L_LINE, li, c)
  return li + 1
end

-- Draws a link between two points.
local function Link(li, ax, ay, bx, by, c)
  if math.abs(ax - bx) >= 1 and math.abs(ay - by) >= 1 then
    if li >= N.LINE then
      return li
    end
    local len = math.sqrt((bx - ax) ^ 2 + (by - ay) ^ 2)
    Kit.art_quad(L_LINE, li, "line", (ax + bx) / 2, (ay + by) / 2, len, G.LINE)
    -- Rotates by the layer's local z rotation (radians, y up as the layer positions).
    funcLuaMenuCommand(C.ROTATE, L_LINE, 0, 0, math.atan2(-(by - ay), bx - ax), li)
    Kit.colour(L_LINE, li, c)
    return li + 1
  end
  return Bar(li, ax, bx, ay, by, c)
end

local function DrawLinks()
  local li, ai = 0, N.ARROW0
  page_arrows = {}
  for a, tile in ipairs(B.tiles) do
    for _, b in ipairs(tile.links) do
      if a < b and (pos[a] ~= nil or pos[b] ~= nil) then
        local c = LinkColour(a, b)
        if pos[a] ~= nil and pos[b] ~= nil then
          li = Link(li, pos[a][1], pos[a][2], pos[b][1], pos[b][2], c)
        else
          -- Routes the link towards a page that is not on screen (3 or more pages).
          local u, v = a, b
          if pos[u] == nil then
            u, v = b, a
          end
          local right = B.tiles[v].page > B.tiles[u].page
          local k = Shown(B.tiles[u].page)
          local edge = PageLeft(k) + (right and B.cols * cell or 0)
          li = Bar(li, pos[u][1], edge, pos[u][2], pos[u][2], c)
          if ai < N.UI then
            Kit.art_quad(L_UI, ai, right and "arrow_r" or "arrow_l", edge + (right and 30 or -30), pos[u][2], G.ARROW, G.ARROW)
            page_arrows[#page_arrows + 1] = {edge + (right and 30 or -30), pos[u][2], v}
            ai = ai + 1
          end
        end
      end
    end
  end
  for i = li, N.LINE - 1 do
    Kit.hide_off_screen(L_LINE, i)
  end
  for i = ai, N.UI - 1 do
    Kit.hide_off_screen(L_UI, i)
  end
end

local function DrawPanels()
  -- no panels and no page titles (the board sits on the IE3 background, nothing above it)
  for k = 1, N.BG do
    Kit.hide_off_screen(L_BG, k - 1)
    Kit.hide_off_screen(L_UI, k)
  end
  if not help_open then
    for i = 0, N.TITLE - 1 do
      Kit.hide_off_screen(L_TITLE, i)
    end
  end
end

local HELP = {CX = 960, CY = 600, W = 860, LINE = 88, PAD = 20, BADGE = 64, BADGE_X = 56, TEXT_X = 642, SEP = 2,
              SEP_COLOUR = {0.192, 0.224, 0.451}}

local function DrawHelp()
  if not help_open then
    Kit.hide_off_screen(L_HELP, 0)
    for i = ICON_BADGE0, ICON_HELP_END - 1 do
      Kit.hide_off_screen(L_ICON, i)
    end
    for i = 0, N.TITLE - 1 do
      Kit.hide_off_screen(L_TITLE, i)
    end
    return
  end
  local list = VRFW.match_rank ~= nil and VRFW.match_rank.list() or {}
  local n = math.min(#list, N.TITLE, ICON_SEP0 - ICON_BADGE0)
  local left = HELP.CX - HELP.W / 2
  Kit.art_quad(L_HELP, 0, "help_panel", HELP.CX, HELP.CY, HELP.W, n * HELP.LINE + 2 * HELP.PAD)
  for i = 1, n do
    local r = list[i]
    local y = HELP.CY + (i - (n + 1) / 2) * HELP.LINE
    RankBadge(L_ICON, ICON_BADGE0 + i - 1, r, left + HELP.BADGE_X, y, HELP.BADGE)
    local si = ICON_SEP0 + i - 2   -- the separator above every row but the first
    if i > 1 and si < ICON_HELP_END then
      Kit.art_quad(L_ICON, si, "line", HELP.CX, y - HELP.LINE / 2, HELP.W - 32, HELP.SEP)
      Kit.colour(L_ICON, si, HELP.SEP_COLOUR)
    end
    Kit.show(L_TITLE, i - 1)
    funcLuaMenuCommand(C.TEXT, L_TITLE, TEXT_ON, r.text ~= "" and Kit.text(CRC32(r.text)) or VRFW.match_rank.label(r.id), i - 1)
    funcLuaMenuCommand(C.TEXT_VISIBLE, L_TITLE, TEXT_ON, true, i - 1)
    Kit.place(L_TITLE, i - 1, HELP.TEXT_X - TEXT_DX, y)
  end
  for i = ICON_BADGE0 + n, ICON_SEP0 - 1 do
    Kit.hide_off_screen(L_ICON, i)
  end
  for i = ICON_SEP0 + math.max(0, n - 1), ICON_HELP_END - 1 do
    Kit.hide_off_screen(L_ICON, i)
  end
  for i = n, N.TITLE - 1 do
    Kit.hide_off_screen(L_TITLE, i)
  end
end

local function SetHelp(on)
