local function ReqText(tile)
  local parts = {}
  for _, r in ipairs(tile.requires or {}) do
    local row = T.REQ[r.kind]
    if row ~= nil then
      if r.kind == "team_level" then
        parts[#parts + 1] = Kit.format(row, tonumber(r.value) or 0, VRFW.chain.req_have(r))
      else
        parts[#parts + 1] = Kit.format(row, r.name ~= "" and r.name or tostring(r.value))
      end
    end
  end
  return table.concat(parts, "  ·  ")
end

local function RewardName(r)
  local what = r.name
  if (r.text or 0) ~= 0 and Kit.text(r.text) ~= "" then
    what = Kit.text(r.text)                 -- the declared label (`Text`: a menu_text row)
  elseif r.kind == "emblem" then
    what = Kit.text(T.PRIZE_EMBLEM)
  elseif r.kind == "kit" then
    what = Kit.text(T.PRIZE_KIT)
  elseif what == nil or what == "" then
    what = Kit.text(T.PRIZE_ITEM)
  end
  if r.paid then
    what = Kit.format(T.REWARD_GOT, what)
  end
  return what
end

-- match tile t's rank rewards in rank order (the lower rank first), at most N.REWARD
local function SortedRewards(t)
  local list = {}
  for k, r in ipairs(VRFW.chain.rank_rewards ~= nil and VRFW.chain.rank_rewards(B, t) or {}) do
    list[#list + 1] = {r = r, k = k, order = VRFW.match_rank ~= nil and VRFW.match_rank.order(r.rank) or 0}
  end
  table.sort(list, function(a, b)
    if a.order ~= b.order then
      return a.order < b.order
    end
    return a.k < b.k
  end)
  local out = {}
  for i = 1, math.min(#list, N.REWARD) do
    out[i] = list[i].r
  end
  return out
end

-- Collects the items a match drops (the game's drop tables after the build).
local drops_of = {}
local function MatchDrops(tile)
  local game, difficulty = tonumber(tile.game) or 0, tonumber(tile.difficulty) or 0
  local key = game .. ":" .. difficulty
  if drops_of[key] ~= nil then
    return drops_of[key]
  end
  local out, seen = {}, {}
  local function add(id)
    if type(id) == "number" and id ~= 0 and not seen[id] and #out < N.DROP then
      seen[id] = true
      out[#out + 1] = id
    end
  end
  if game ~= 0 then
    local r = table.pack(pcall(funcLuaCommand, C.DROP_PREVIEW, game, N.DROP, difficulty))
    if r[1] then
      for k = 2, r.n do
        add(r[k])
      end
    end
    if #out < N.DROP then
      local q = table.pack(pcall(funcLuaCommand, C.DROP_LIST_OF, game, difficulty, 0, 4 * N.DROP))
      if q[1] then
        for k = 3, q.n, 2 do      -- total, then item, percent per row
          add(q[k])
        end
      end
    end
  end
  drops_of[key] = out
  Log("drops of game", game, "difficulty", difficulty, #out)
  return out
end

-- Returns a box line's width at text scale 1.
local function LineWidth(i, s)
  Kit.scale(L_CARDTXT, i, 1, 1)
  local ok, w = pcall(funcLuaMenuCommand, C.TEXT_SIZE, L_CARDTXT, i, TEXT_ON, s)
  if ok and type(w) == "number" and w > 0 then
    return w
  end
  local chars = string.gsub(s, "[\128-\191]", "")
  return #chars * BOX.GLYPH_W
end

-- an item's own game icon on a transparent quad (the "?" icon when the game has none)
local function ItemIcon(idx, item, x, y, size, tint)
  local tc, sc = VRFW.screen_art.plain("blank")
  Kit.textured_quad(L_ICON, idx, tc, sc, x, y, size, size)
  local ok, r = pcall(funcLuaMenuCommand, C.ITEM_ICON, L_ICON, idx, MESH_QUAD, NODE_QUAD, item)
  if not ok or r == false then
    Kit.art_quad(L_ICON, idx, "icon_unknown", x, y, size, size)
    return
  end
  Kit.colour(L_ICON, idx, tint)
end

local function HideRewardsBox()
  Kit.hide_off_screen(L_CARD, 1)
  for i = ICON_REWARD0, N.ICON - 1 do
    Kit.hide_off_screen(L_ICON, i)
  end
  for i = TXT_REWARD0, N.CARDTXT - 1 do
    Kit.hide_off_screen(L_CARDTXT, i)
  end
end

-- Draws match tile t's rewards box centred on cx.
local function DrawRewardsBox(t, cx)
  local tile = B.tiles[t]
  local rewards, drops = SortedRewards(t), MatchDrops(tile)
  if #rewards == 0 and #drops == 0 then
    HideRewardsBox()
    return
  end
  Kit.art_quad(L_CARD, 1, "card", cx, CARD.CY, BOX.W, CARD.H)
  local left, top, row_w = cx - BOX.W / 2 + BOX.PAD, CARD.CY - CARD.H / 2, BOX.W - 2 * BOX.PAD
  local n = #rewards
  local names, widths, total = {}, {}, 0
  for i = 1, n do
    names[i] = RewardName(rewards[i])
    widths[i] = LineWidth(TXT_REWARD0 + i - 1, names[i]) * BOX.NAME_S
    total = total + widths[i]
  end
  local room = row_w - n * BOX.NAME_DX - math.max(0, n - 1) * BOX.GAP
  local k = (total > room and total > 0) and room / total or 1
  local x, y = left, top + BOX.ROW_Y
  for i = 1, N.REWARD do
    local r = rewards[i]
    local badge, icon = ICON_REWARD0 + 2 * (i - 1), ICON_REWARD0 + 2 * (i - 1) + 1
    if r == nil then
      Kit.hide_off_screen(L_ICON, badge)
      Kit.hide_off_screen(L_ICON, icon)
      CardLine(TXT_REWARD0 + i - 1, nil)
    else
      if k == 1 then
        local rest = (n - i) * BOX.GAP
        for j = i, n do
          rest = rest + BOX.NAME_DX + widths[j]
        end
        x = math.max(x, math.min(left + (i - 1) * row_w / n, left + row_w - rest))
      end
      local tint = r.paid and BOX.PAID_TINT or COLOUR.WHITE
      local rdef = VRFW.match_rank ~= nil and VRFW.match_rank.by_id(r.rank) or nil
      RankBadge(L_ICON, badge, rdef, x + BOX.BADGE / 2, y, BOX.BADGE)
      Kit.colour(L_ICON, badge, tint)
      ItemIcon(icon, r.id, x + BOX.ICON_DX + BOX.ICON / 2, y, BOX.ICON, tint)
      CardLine(TXT_REWARD0 + i - 1, names[i], x + BOX.NAME_DX, y, BOX.NAME_S * k)
      x = x + BOX.NAME_DX + widths[i] * k + BOX.GAP
    end
  end
  -- the line between the two parts, only when both have something
  if n > 0 and #drops > 0 then
    Kit.art_quad(L_ICON, ICON_RULE, "line", cx, top + BOX.RULE_Y, row_w, BOX.RULE)
    Kit.colour(L_ICON, ICON_RULE, BOX.RULE_COLOUR)
  else
    Kit.hide_off_screen(L_ICON, ICON_RULE)
  end
  -- Draws the drops.
  for j = 1, N.DROP do
    if drops[j] == nil then
      Kit.hide_off_screen(L_ICON, ICON_DROP0 + j - 1)
      CardLine(TXT_DROP0 + j - 1, nil)
    else
      local dx = left + ((j - 1) % 2) * row_w / 2
      local dy = top + BOX.DROP_Y + math.floor((j - 1) / 2) * BOX.DROP_PITCH
      Kit.art_quad(L_ICON, ICON_DROP0 + j - 1, "icon_unknown", dx + BOX.DROP_ICON / 2, dy, BOX.DROP_ICON, BOX.DROP_ICON)
      CardLine(TXT_DROP0 + j - 1, Kit.text(T.DROP_UNKNOWN), dx + BOX.DROP_NAME_DX, dy, BOX.NAME_S)
    end
  end
end

-- Draws the focused tile's card above the board.
local function DrawCard()
  local tile = B and B.tiles[focus]
  if tile == nil then
    Kit.hide_off_screen(L_CARD, 0)
    Kit.hide_off_screen(L_ICON, ICON_CREST)
    for i = 0, N.CARDTXT - 1 do
      Kit.hide_off_screen(L_CARDTXT, i)
    end
    HideRewardsBox()
    return
  end
  local cx = CARD.BOARD_CX
  Kit.art_quad(L_CARD, 0, "card", cx, CARD.CY, CARD.W, CARD.H)
  local open = VRFW.chain.open(B, focus)
  local st = VRFW.chain.tile_state(B, focus)
  local lines, icon = {}, "icon_unknown"
  if tile.kind == "match" and open then
    lines = {tile.rival, Kit.format(T.CARD_LEVEL, tile.level)}
    local r = VRFW.chain.rank_id(B, focus)
    if r ~= nil then
      lines[2] = lines[2] .. "  ·  " .. Kit.format(T.RANK, VRFW.match_rank.label(r))
    end
    -- Adds the tile's match challenge ([[VRFW.MatchChallenge]]).
    local mc = VRFW.match_challenge and VRFW.match_challenge.title_of(tile.game, tile.difficulty, VRFW.chain.done(B, focus))
    lines[2] = lines[2] .. "  |  " .. (mc ~= nil and Kit.format(T.CARD_REQ, mc) or Kit.text(T.CARD_REQ_NONE))
    -- the save's wins against this team (VRFW.stats, at least 1 once the tile is won)
    lines[3] = Kit.format(T.CARD_WINS, VRFW.chain.wins_against(B, focus))
    icon = nil
  elseif tile.kind == "match" then
    lines = {Kit.text(T.CARD_UNKNOWN), Kit.format(T.CARD_LEVEL, tile.level), Kit.text(T.LOCKED)}
  elseif tile.kind == "slot" then
    lines = {Kit.text(T.SLOT)}
  elseif tile.kind == "blocked" then
    local status
    if st ~= "0" then
      status = Kit.text(T.BLOCKED_OPEN)
    elseif VRFW.chain.unblocked(B, focus) then
      status = Kit.text(T.LOCKED)                      -- met: it opens once a tile joined to it is won
    else
      status = Kit.text(T.BLOCKED_RULE)
    end
    lines = {Kit.text(T.CARD_BLOCKED), Kit.format(T.CARD_REQ, ReqText(tile)), status}
    icon = st ~= "0" and "icon_unblocked" or "icon_blocked"
  elseif tile.kind == "schest" then
    lines = {Kit.text(T.CARD_SCHEST), st == "o" and Kit.text(T.CHEST_OPEN) or Kit.text(T.CARD_SCHEST_RULE)}
    icon = st == "o" and "icon_schest_open" or (open and "icon_schest" or "icon_schest_locked")
  elseif tile.kind == "dchest" then
    local status
    if VRFW.chain.d_chest_empty(B, focus) then
      status = Kit.text(T.DCHEST_EMPTY)
    elseif st == "o" then
      status = Kit.text(T.CHEST_OPEN)
    elseif VRFW.chain.d_chest_ready(B, focus) then
      status = Kit.text(T.CARD_CHEST)
    elseif st == "h" or st == "a" then
      status = Kit.text(VRFW.chain.d_chest_waits(B, focus) == "a" and T.DCHEST_HALF_A or T.DCHEST_HALF)
    elseif open then
      -- Handles a chest with no base reward.
      status = Kit.text(VRFW.chain.d_chest_waits(B, focus) == "a" and T.CARD_ACHEST_RULE or T.CARD_SCHEST_RULE)
    else
      status = Kit.text(T.LOCKED)
    end
    lines = {Kit.text(T.CARD_DCHEST), status}
    if not VRFW.chain.d_chest_empty(B, focus) and st ~= "o" then
      lines[3] = Kit.text((tile.areward or "") ~= "" and T.DCHEST_RULE_A or T.DCHEST_RULE)
    end
    icon = DChestIcon(focus)
  elseif tile.kind == "chest" then
    lines = {Kit.text(T.CHEST), st == "o" and Kit.text(T.CHEST_OPEN) or Kit.text(open and T.CARD_CHEST or T.LOCKED)}
    icon = st == "o" and "icon_chest_open" or (open and "icon_chest" or "icon_chest_locked")
  else
    lines = {Kit.text(T.START)}
    local avg = VRFW.chain.average(B)
    if avg ~= nil then
      lines[2] = Kit.format(T.CHAIN_RANK, VRFW.match_rank.label(avg))
    end
    icon = "icon_start"
  end
  -- Keeps the first line in the plate's lighter upper band.
  local ys = {CARD.NAME_Y, CARD.LINE1_Y, CARD.LINE2_Y}
  if #lines == 2 then
    ys = {CARD.NAME_Y, (CARD.LINE1_Y + CARD.LINE2_Y) / 2}
  end
  local x = cx - CARD.W / 2 + CARD.TEXT_DX
  for i = 0, TXT_REWARD0 - 1 do
    CardLine(i, lines[i + 1], x, ys[i + 1] or CARD.CY, i == 0 and CARD.NAME_S or CARD.LINE_S)
  end
  -- Handles an open match tile.
  if tile.kind == "match" and open then
    DrawRewardsBox(focus, BOX.CX)
  else
    HideRewardsBox()
  end
  local ix = cx + CARD.W / 2 - CARD.CREST_DX
  if icon == nil then
    local tc, sc = Emblem(tile)
    if tc == false then
      Kit.hide_off_screen(L_ICON, ICON_CREST)     -- still loading: Step redraws
    elseif tc == nil then
      Kit.art_quad(L_ICON, ICON_CREST, "icon_unknown", ix, CARD.CY, CARD.CREST, CARD.CREST)
    else
      Kit.textured_quad(L_ICON, ICON_CREST, tc, sc, ix, CARD.CY, CARD.CREST, CARD.CREST)
    end
  else
    Kit.art_quad(L_ICON, ICON_CREST, icon, ix, CARD.CY, CARD.CREST, CARD.CREST)
  end
end

