              BADGE = 48, BADGE_DX = 52}
local LIST_TINT = {FOCUS = {1, 1, 1}, DONE = {0.62, 0.85, 0.66}, PLAIN = {0.72, 0.74, 0.82}}   -- the focused row the brightest

