local function DrawHubCard()
  local b = HUB[hfocus]
  Kit.art_quad(L_CARD, 0, "card", CARD.CX, CARD.CY, CARD.W, CARD.H)
  local line2 = Kit.format(T.HUB_MATCHES, VRFW.chain.won(b), b.matches)
  local avg = VRFW.chain.average(b)
  if avg ~= nil then
    line2 = Kit.format(T.CHAIN_RANK, VRFW.match_rank.label(avg))
  end
  local lines = {b.title, line2, Kit.text(T.HUB_OPEN)}
  local ys = {CARD.NAME_Y, CARD.LINE1_Y, CARD.LINE2_Y}
  for i = 0, TXT_REWARD0 - 1 do
    CardLine(i, lines[i + 1], CARD.CX - CARD.W / 2 + CARD.TEXT_DX, ys[i + 1], i == 0 and CARD.NAME_S or CARD.LINE_S)
  end
  HideRewardsBox()
  DrawCrest(L_ICON, ICON_CREST, ChainCrestTile(b), CARD.CX + CARD.W / 2 - CARD.CREST_DX, CARD.CY, CARD.CREST)
end

local function DeclareZones()
  Ptr.begin()
  if mode == "list" then
    for i, p in pairs(pos) do
      Ptr.box(p[1], p[2], LIST.W / 2, LIST.ROW / 2, i)
    end
  elseif B ~= nil then
    local hw = cell / 2
    if B.layout == "hex" then
      hw = cell * G.HEX_DX / 2
    end
    for t, p in pairs(pos) do
      Ptr.box(p[1], p[2], hw, cell / 2, t)
    end
    for _, a in ipairs(page_arrows) do
      Ptr.box(a[1], a[2], G.ARROW / 2, G.ARROW / 2, {arrow = a[3]})
    end
  end
  Ptr.forget()
end

local function DrawList()
  Kit.begin()
  pos, slot_of = {}, {}
  DrawBackground()
  for s = 0, N.TILE - 1 do
    Kit.hide_off_screen(L_TILE, s)
    Kit.hide_off_screen(L_EMB, s)
    Kit.hide_off_screen(L_TAG, s)
  end
  for i = 0, N.LINE - 1 do
    Kit.hide_off_screen(L_LINE, i)
  end
  for i = 0, N.UI - 1 do
    Kit.hide_off_screen(L_UI, i)
  end
  for i = 0, N.BG - 1 do
    Kit.hide_off_screen(L_BG, i)
  end
  Kit.hide_off_screen(L_HELP, 0)
  for i = ICON_BADGE0, N.ICON - 1 do
    Kit.hide_off_screen(L_ICON, i)
  end
  local left = LIST.CX - LIST.W / 2
  local rows = ListRows()
  for k = 0, rows - 1 do
    local i = htop + k
    local b = HUB[i]
    if b == nil then
      Kit.hide_off_screen(L_TITLE, k)
    else
      local y = LIST.TOP + k * LIST.ROW
      Kit.art_quad(L_TILE, k, "card", LIST.CX, y, LIST.W, LIST.H)
      Kit.colour(L_TILE, k, i == hfocus and LIST_TINT.FOCUS or (VRFW.chain.complete(b) and LIST_TINT.DONE or LIST_TINT.PLAIN))
      DrawCrest(L_EMB, k, ChainCrestTile(b), left + LIST.CREST_DX, y, LIST.CREST)
      Kit.show(L_TITLE, k)
      Kit.scale(L_TITLE, k, 1, 1)
      funcLuaMenuCommand(C.TEXT, L_TITLE, TEXT_ON, b.title .. "   " .. VRFW.chain.won(b) .. " / " .. b.matches, k)
      funcLuaMenuCommand(C.TEXT_VISIBLE, L_TITLE, TEXT_ON, true, k)
      Kit.place(L_TITLE, k, left + LIST.TEXT_DX - TEXT_DX, y)
      local avg = VRFW.chain.average(b)
      local rdef = avg ~= nil and VRFW.match_rank ~= nil and VRFW.match_rank.by_id(avg) or nil
      RankBadge(L_TAG, k, rdef, left + LIST.W - LIST.BADGE_DX, y, LIST.BADGE)
      pos[i] = {LIST.CX, y}
    end
  end
  for k = rows, N.TITLE - 1 do
    Kit.hide_off_screen(L_TITLE, k)
  end
  -- Draws the arrows for more chains above or below.
  local ai = N.ARROW0
  if htop > 1 then
    Kit.art_quad(L_UI, ai, "arrow_r", LIST.CX, LIST.TOP - LIST.ROW * 0.62, G.ARROW, G.ARROW)
    funcLuaMenuCommand(C.ROTATE, L_UI, 0, 0, math.pi / 2, ai)
    ai = ai + 1
  end
  if htop + rows - 1 < #HUB then
    Kit.art_quad(L_UI, ai, "arrow_r", LIST.CX, LIST.TOP + (rows - 0.38) * LIST.ROW, G.ARROW, G.ARROW)
    funcLuaMenuCommand(C.ROTATE, L_UI, 0, 0, -math.pi / 2, ai)
  end
  HideGuideLine()
  DrawHubCard()
  DeclareZones()
end

local function SetHubFocus(i, sound)
  if HUB == nil or i == nil or i < 1 or i > #HUB or i == hfocus then
    return
  end
  hfocus = i
  local rows = ListRows()
  if hfocus < htop then
    htop = hfocus
  elseif hfocus > htop + rows - 1 then
    htop = hfocus - rows + 1
  end
  if sound then
    funcLuaCommand(C.SE, SE_OK)
  end
  DrawList()
end

local function FirstFocus()
  for _, t in ipairs(VRFW.chain.sync(B)) do
    Log("unblocked", B.key, B.tiles[t].id)
  end
  focus = B.start
  for t, tile in ipairs(B.tiles) do
    if tile.kind == "match" and VRFW.chain.open(B, t) and not VRFW.chain.done(B, t) then
      focus = t
      break
    end
  end
  view = math.max(0, math.min(B.tiles[focus].page, Pages() - 2))
end

local DrawAll   -- defined below (ShowBoard / ShowList call it)

-- Shows the board of a hub.
local function ShowBoard(b)
  B = b
  mode = "board"
  help_open = false
  FirstFocus()
  for k = 0, N.TITLE - 1 do
    Kit.hide_off_screen(L_TITLE, k)
  end
  for i = 0, N.UI - 1 do
    funcLuaMenuCommand(C.ROTATE, L_UI, 0, 0, 0, i)   -- the list's turned arrows back straight
  end
  UpdateTitle()
  UpdateButtonGuide()
  DrawAll()
  Log("hub board", B.key, "state", VRFW.chain.state(B))
end

local function ShowList()
  mode = "list"
  help_open = false
  UpdateTitle()
  UpdateButtonGuide()
  DrawAll()
end

DrawAll = function()
  if mode == "list" then
    return DrawList()
  end
  if B == nil then
    return
  end
  Kit.begin()
  DrawBackground()
  Layout()
  DrawPanels()
  for s = 0, N.TILE - 1 do
    Kit.hide_off_screen(L_TILE, s)
    Kit.hide_off_screen(L_EMB, s)
    Kit.hide_off_screen(L_TAG, s)
  end
  for t in pairs(pos) do
    DrawTile(t)
  end
  DrawLinks()
  DrawCursor()
  HideGuideLine()
  DrawCard()
  DrawHelp()
  DeclareZones()
end

local function Ask(text)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  local yes = VRFW.question.ask(text)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
  return yes
end

local function Message(text, button)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  VRFW.question.notice(text, {button = button})
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
end

local function ItemGet(id)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  VRFW.question.item_get(id)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
end

local function Close(result)
  VRFW.param.replace(KEY_RESULT, result)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  funcLuaCommand(C.CLOSE_MENU, MENU)
end

-- Pays a chest that is declared or already paid.
local function PayChest(t)
  local given, why, skipped = VRFW.chain.pay(B, t)
  if given == nil then
    if why == "full" or why == "bank_full" then
      funcLuaCommand(C.SE, SE_NG)
      Message(Kit.text(why == "full" and T.CHEST_FULL or T.CHEST_BANK_FULL), C.MSG_BUTTON_ACCEPT)
      return "waits"
    end
    return false
  end
  for _, r in ipairs(given) do
    funcLuaCommand(C.SE, SE_DECIDE)
    if r.kind == "item" then
      ItemGet(r.id)
    else
      Message(Kit.text(T.CHEST_PLAYER), C.MSG_BUTTON_ACCEPT)
    end
  end
  return #given > 0 or (skipped or 0) > 0  -- a chest of already owned rewards is not an empty one
end

local function PayPending()
  for _, t in ipairs(VRFW.chain.unpaid(B)) do
    Log("chest pays late", B.key, B.tiles[t].id)
    if PayChest(t) == "waits" then
      break
    end
  end
  if VRFW.chain.news == nil then
    return
  end
  for _, t in ipairs(VRFW.chain.rank_unpaid(B)) do
    Log("rank reward pays late", B.key, B.tiles[t].id)
    local given = VRFW.chain.pay_rank(B, t, true)
    if given == nil then
      funcLuaCommand(C.SE, SE_NG)
      Message(Kit.text(T.RANK_FULL), C.MSG_BUTTON_ACCEPT)
      break
    end
  end
  local news = VRFW.chain.news(B)
  VRFW.chain.clear_news(B)
  for _, r in ipairs(news) do
    funcLuaCommand(C.SE, SE_DECIDE)
    ItemGet(r.id)
  end
  if #news > 0 then
    DrawCard()
  end
end

local function Decide()
  local tile = B and B.tiles[focus]
  if tile == nil or tile.kind == "start" then
    funcLuaCommand(C.SE, SE_OK)
    return
  end
  if tile.kind == "slot" then
    funcLuaCommand(C.SE, SE_NG)
    Message(Kit.text(T.SLOT), C.MSG_BUTTON_ACCEPT)
    return
  end
  if tile.kind == "blocked" then
    if VRFW.chain.done(B, focus) then
      funcLuaCommand(C.SE, SE_OK)
      return
    end
    funcLuaCommand(C.SE, SE_NG)
    Log("blocked", tile.id)
    Message(Kit.format(T.BLOCKED_MSG, ReqText(tile)), C.MSG_BUTTON_ACCEPT)
    return
  end
  if tile.kind == "dchest" and VRFW.chain.d_chest_empty(B, focus) then
    funcLuaCommand(C.SE, SE_NG)
    Log("dchest disabled", tile.id)
    Message(Kit.text(T.DCHEST_EMPTY), C.MSG_BUTTON_ACCEPT)
    return
  end
  if not VRFW.chain.open(B, focus) then
    funcLuaCommand(C.SE, SE_NG)
    Log("locked", tile.id)
    Message(Kit.text(tile.kind == "schest" and T.SCHEST or T.LOCKED_MSG), C.MSG_BUTTON_ACCEPT)
    return
  end
  if tile.kind == "dchest" then
    local st = VRFW.chain.tile_state(B, focus)
    if st == "o" then
      funcLuaCommand(C.SE, SE_OK)
      return
    end
    if not VRFW.chain.d_chest_ready(B, focus) then
      funcLuaCommand(C.SE, SE_NG)
      local waits = VRFW.chain.d_chest_waits(B, focus)
      Log("dchest waits for", waits, tile.id, st)
      if st == "h" or st == "a" then
        Message(Kit.text(waits == "a" and T.DCHEST_HALF_A or T.DCHEST_HALF), C.MSG_BUTTON_ACCEPT)
      else
        Message(Kit.text(waits == "a" and T.CARD_ACHEST_RULE or T.SCHEST), C.MSG_BUTTON_ACCEPT)
      end
      return
    end
    funcLuaCommand(C.SE, SE_DECIDE)
    VRFW.chain.open_chest(B, focus)
    DrawAll()
    if not PayChest(focus) then
      Message(Kit.text(T.CHEST_OPENED), C.MSG_BUTTON_ACCEPT)
    end
    return
  end
  if tile.kind == "chest" or tile.kind == "schest" then
    if VRFW.chain.done(B, focus) then
      funcLuaCommand(C.SE, SE_OK)
      return
    end
    funcLuaCommand(C.SE, SE_DECIDE)
    VRFW.chain.open_chest(B, focus)
    DrawAll()
    if not PayChest(focus) then
      Message(Kit.text(T.CHEST_OPENED), C.MSG_BUTTON_ACCEPT)
    end
    return
  end
  -- Checks the tile's match challenge.
  local challenge = VRFW.match_challenge
  local beaten = VRFW.chain.done(B, focus)
  local refusal = challenge and challenge.refusal(tile.game, 0, tile.difficulty, beaten)
  local supplied = false
  if refusal ~= nil then
    if challenge.supply_row(tile.game, tile.difficulty) ~= nil and not challenge.club_can_field(challenge.of(tile.game, tile.difficulty), 0) then
      supplied = true
      Log("challenge: the club cannot field it, supplied squad", tile.id)
      Message(Kit.text(T.MC_SUPPLIED), C.MSG_BUTTON_ACCEPT)
    else
      funcLuaCommand(C.SE, SE_NG)
      Log("challenge refused", tile.id)
      Message(refusal, C.MSG_BUTTON_ACCEPT)
      return
    end
  end
  funcLuaCommand(C.SE, SE_DECIDE)
  if not Ask(Kit.format(T.ASK, tile.rival, tile.level)) then
    Log("match declined", tile.id)
    return
  end
  Log("match", B.key, tile.id, "game", tile.game, "difficulty", tile.difficulty, "level", tile.level)
  VRFW.param.clear(VRFW.chain.P_SUPPLIED)
  if supplied then
    VRFW.param.set(VRFW.chain.P_SUPPLIED, 1)
  end
  VRFW.param.clear(KEY_PICK_CHAIN)
  if HUB ~= nil then
    VRFW.param.set(KEY_PICK_CHAIN, B.i + 1)   -- the opener plays the tile of THIS chain
  end
  Close(focus)
end

local function SetFocus(t, sound)
  if B == nil or t == nil or t < 1 or t > #B.tiles or t == focus then
    return
  end
  focus = t
  if sound then
    funcLuaCommand(C.SE, SE_OK)
  end
  local p = B.tiles[t].page
  if Shown(p) == nil then
    view = p < view and p or math.max(0, p - 1)
    DrawAll()
    return
  end
  DrawCursor()
  DrawCard()
end

local function BoardPlace(t)
  local tile = B.tiles[t]
  if B.layout == "hex" then
    return tile.col * G.HEX_DX, tile.row + (tile.col % 2) * 0.5   -- the honeycomb's half rows
  end
  return tile.page * (B.cols + G.GAP) + tile.col, tile.row
end

-- two directions closer than this (as cosines) are a tie
local SAME_FIT = 0.000001

-- Moves the focus the way an arrow follows the lines.
local function MoveFocus(dx, dy)
  if B == nil then
    return
  end
  local x, y = BoardPlace(focus)
  local min_fit = math.cos(B.direction_tolerance_degrees * math.pi / 180) - SAME_FIT
  local best, best_fit, best_side = nil, nil, nil
  for _, j in ipairs(B.tiles[focus].links) do
    local jx, jy = BoardPlace(j)
    local fit = ((jx - x) * dx + (jy - y) * dy) / math.sqrt((jx - x) ^ 2 + (jy - y) ^ 2)
    local side = dx ~= 0 and jy or jx
    if fit >= min_fit and (best == nil or fit > best_fit + SAME_FIT or (fit >= best_fit - SAME_FIT and side < best_side)) then
      best, best_fit, best_side = j, fit, side
    end
  end
  SetFocus(best, true)
end

local function StartCo(fn, arg)
  if vrfw_co ~= nil then
    return
  end
  vrfw_co = coroutine.create(fn)
  local ok, err = coroutine.resume(vrfw_co, arg)
  if not ok then
    PRINT("vrfw_chain_board_menu: " .. tostring(err))
    Log("error", tostring(err))
    vrfw_co = nil
    funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
  elseif coroutine.status(vrfw_co) == "dead" then
    vrfw_co = nil
  end
end

-- Handles the wheel on a board of 3 or more pages.
local function PageStep(d)
  if B == nil or Pages() <= OnScreen() then
    return
  end
  local v = math.max(0, math.min(view + d, Pages() - 2))
  if v == view then
    return
  end
  view = v
  if Shown(B.tiles[focus].page) == nil then
    local into = d > 0 and view + 1 or view
    local row, best, bd = B.tiles[focus].row, nil, nil
    for t, tile in ipairs(B.tiles) do
      if tile.page == into then
        local dist = math.abs(tile.row - row) * 100 + (d > 0 and tile.col or B.cols - tile.col)
        if bd == nil or dist < bd then
          best, bd = t, dist
        end
      end
    end
    focus = best or focus
  end
  funcLuaCommand(C.SE, SE_OK)
  DrawAll()
end

-- Polls the pointer (zones declared by DeclareZones on each redraw).
local function PollPointer()
  local ev = Ptr.poll()
  if vrfw_co ~= nil or not ready or open_guard > 0 then
    return
  end
  if mode == "list" then
    if type(ev.hover) == "number" and ev.hover ~= hfocus then
      SetHubFocus(ev.hover, true)
    end
    if type(ev.click) == "number" then
      SetHubFocus(ev.click, false)
      funcLuaCommand(C.SE, SE_DECIDE)
      ShowBoard(HUB[hfocus])
    elseif ev.wheel ~= nil then
      SetHubFocus(hfocus + ev.wheel, true)
    end
    return
  end
  if help_open then
    if ev.click ~= nil or ev.miss then
      funcLuaCommand(C.SE, SE_BACK)
      SetHelp(false)
    end
    return
  end
  if type(ev.hover) == "number" and ev.hover ~= focus then
    SetFocus(ev.hover, true)
  end
  if type(ev.click) == "number" then
    SetFocus(ev.click, false)
    StartCo(Decide)
  elseif type(ev.click) == "table" then
    SetFocus(ev.click.arrow, true)
  elseif ev.wheel ~= nil then
    PageStep(ev.wheel)
  end
end

local function OnTextureIn()
  tex_changed = true
end

function OnInit()
  Log = VRFW.logger.new("chain_board")
  Kit = VRFW.screen_kit.new({log = Log, on_texture = OnTextureIn, art = VRFW.screen_art.get(ART_SCREEN), fallback = FALLBACK})
  Ptr = Kit.pointer()
  VRFW.param.clear(KEY_RESULT)
  VRFW.param.clear(KEY_PICK_CHAIN)
  for _, path in ipairs(VRFW.screen_art.atlases(ART_SCREEN)) do
    Kit.texture(path)
  end
  ready = false
  open_guard = 20
  B = nil
  pay_check = nil
  local i = -1
  if VRFW.param.has(KEY_CHAIN) then
    i = Int(VRFW.param.get(KEY_CHAIN))
    VRFW.param.clear(KEY_CHAIN)
  end
  HUB, mode, hfocus, htop = nil, "board", 1, 1
  local hub_slot = nil
  if VRFW.param.has(KEY_HUB) then
    hub_slot = Int(VRFW.param.get(KEY_HUB))
    VRFW.param.clear(KEY_HUB)
  end
  if VRFW.chain == nil then
    Log("error", "VRFW.chain missing (the menu part's lua\\_all\\30_chain.lua did not run in this VM)")
  else
    B = VRFW.chain.board(i)
    if hub_slot ~= nil and VRFW.chain.hub ~= nil then
      HUB = VRFW.chain.hub(hub_slot)
    end
  end
  if HUB ~= nil then
    -- Shows a chain hub.
    mode = "list"
    for k, b in ipairs(HUB) do
      if not VRFW.chain.complete(b) then
        hfocus = k
        break
      end
    end
    htop = math.max(1, math.min(hfocus, #HUB - ListRows() + 1))
    B = HUB[hfocus]
    Log("open hub", hub_slot, "chains", #HUB, "focus", B.key)
    return
  end
  if B == nil then
    Log("open", "chain", i, "no board: closing")
    return
  end
  FirstFocus()
  Log("open", B.key, "tiles", #B.tiles, "pages", Pages(), "state", VRFW.chain.state(B), "focus", B.tiles[focus].id, "rank", VRFW.chain.average(B))
end

-- The tile plates keep no engine mouse zone.
local function DropEngineZone(layer, idx)
  pcall(funcLuaMenuCommand, C.HIT_ZONE, layer, idx, false)
  pcall(funcLuaMenuCommand, C.HOVER_FOCUS, layer, idx, false)
end

local function OpenOwnLayers()
  for i = 0, N.BG - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_BG, i)
  end
  for i = 0, N.LINE - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_LINE, i)
  end
  for i = 0, N.TILE - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_TILE, i)
    DropEngineZone(L_TILE, i)
    funcLuaMenuCommand(C.OPEN_LAYER, L_EMB, i)
    funcLuaMenuCommand(C.OPEN_LAYER, L_TAG, i)
  end
  for i = 0, N.UI - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_UI, i)
  end
  for i = 0, N.TITLE - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_TITLE, i)
  end
  funcLuaMenuCommand(C.OPEN_LAYER, L_BACK, 0)
  for i = 0, N.HELP - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_HELP, i)
  end
  for i = 0, N.CARD - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_CARD, i)
  end
  for i = 0, N.CARDTXT - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_CARDTXT, i)
  end
  for i = 0, N.ICON - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_ICON, i)
  end
end

function OnSetupLayer(a1, a2)
  Kit.forget()                  -- a layer that (re)opens has none of the commands sent so far
  if a1 == L_HEADER then
    SetupSoccerTopCommonHeaderLayerInfo(a1, 4153539961, 253801632, 3969848060, 1144161661, 3293713115, 253801632, 1152304044, 305955024, 3007971317)
    UpdateHeader(3586861540)
    UpdateTitle()
    OpenOwnLayers()
  elseif a1 == L_ROW or a1 == L_TITLE or a1 == L_CARDTXT then
    -- Sets the list item.
    funcLuaMenuCommand(C.TEXT, a1, TEXT_ON, "", a2)
    funcLuaMenuCommand(C.TEXT, a1, TEXT_OFF, "", a2)
    funcLuaMenuCommand(C.TEXT_VISIBLE, a1, TEXT_ON, a1 ~= L_ROW, a2)
    funcLuaMenuCommand(C.TEXT_VISIBLE, a1, TEXT_OFF, false, a2)
    for _, m in ipairs(ROW_MESHES) do
      funcLuaMenuCommand(C.MESH_VISIBLE, a1, m, false, a2)
    end
    funcLuaMenuCommand(C.ATTACH_TRACE, a1, a2, CUR, false)
    if a1 ~= L_ROW then
      Kit.hide_off_screen(a1, a2)
    end
  elseif a1 == L_RETAIL_BG then
    -- Hides the layer when a mod declares the background (role background, DrawBackground).
    funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, VRFW.screen_art.role(ART_SCREEN, "background") == nil)
  elseif a1 == L_BG or a1 == L_LINE or a1 == L_TILE or a1 == L_EMB or a1 == L_TAG or a1 == L_UI or a1 == L_BACK or a1 == L_HELP
      or a1 == L_CARD or a1 == L_ICON then
    Kit.hide_off_screen(a1, a2)                -- DrawAll draws what is used when the anchor opens
    if a1 == L_TILE then
      DropEngineZone(a1, a2)
    end
  elseif a1 == L_GUIDE_LINE then
    HideGuideLine()
  elseif a1 == L_BTN_GUIDE then
    UpdateButtonGuide()
  end
end

function OnOpenLayer(a1, a2)
  Kit.forget()                  -- a layer that (re)opens has none of the commands sent so far
  if a1 == L_ROW and a2 == 0 then
    Kit.open_list_anchor(a1, L_CURSOR, CUR)
    if B == nil then
      Close(0)
      return
    end
    DrawAll()
    UpdateButtonGuide()
    Ptr.reset()
    DeclareZones()              -- Reset forgot the zones DrawAll declared
    ready = true
    if funcLuaCommand(C.FADE_DONE) then
      funcLuaCommand(C.FADE, 0, 0.3)
    end
  elseif a1 == L_GUIDE_LINE then
    HideGuideLine()
  end
end

function OnDecideFocus(a1, a2)
  if vrfw_co ~= nil or not ready or open_guard > 0 or Ptr.owns() then
    return                      -- a pointer click is the pointer's (PollPointer)
  end
  if help_open then
    funcLuaCommand(C.SE, SE_BACK)
    SetHelp(false)
    return
  end
  if mode == "list" then
    funcLuaCommand(C.SE, SE_DECIDE)
    ShowBoard(HUB[hfocus])
    return
  end
  StartCo(Decide)
end

function OnFunction(a1, a2)
  if vrfw_co ~= nil or not ready then
    return 1
  end
  local id = a1
  if a1 ~= FN.UP and a1 ~= FN.DOWN and a1 ~= FN.LEFT and a1 ~= FN.RIGHT and a1 ~= FN.HELP then
    id = a2
  end
  if help_open then
    if id == FN.HELP then
      funcLuaCommand(C.SE, SE_BACK)
      SetHelp(false)
    end
    return 1                    -- the help window is open: arrows do nothing
  end
  if id ~= FN.HELP then
    Ptr.key_step()               -- a key move: the pad owns the focus until the pointer moves again
  end
  if mode == "list" then
    local rows = ListRows()
    if id == FN.UP then
      SetHubFocus(hfocus - 1, true)
    elseif id == FN.DOWN then
      SetHubFocus(hfocus + 1, true)
    elseif id == FN.LEFT then
      SetHubFocus(math.max(1, hfocus - rows), true)
    elseif id == FN.RIGHT then
      SetHubFocus(math.min(#HUB, hfocus + rows), true)
    elseif id ~= FN.HELP then
      return
    end
    return 1                    -- no help window on the list
  end
  if id == FN.UP then
    MoveFocus(0, -1)
  elseif id == FN.DOWN then
    MoveFocus(0, 1)
  elseif id == FN.LEFT then
    MoveFocus(-1, 0)
  elseif id == FN.RIGHT then
    MoveFocus(1, 0)
  elseif id == FN.HELP then
    if open_guard <= 0 then
      funcLuaCommand(C.SE, SE_DECIDE)
      SetHelp(true)
    end
  else
    return
  end
  return 1
end

function OnEnter(a1, a2)
  if a1 == L_BTN or a1 == L_RET then
    return 1
  end
  OnDecideFocus(a1, a2)
end

function OnBack(a1)
  if vrfw_co ~= nil or not ready or open_guard > 0 then
    return 1
  end
  funcLuaCommand(C.SE, SE_BACK)
  if help_open then
    SetHelp(false)
    return 1
  end
  if HUB ~= nil and mode == "board" then
    Log("hub list")
    ShowList()                  -- a hub's board: back to its list
    return 1
  end
  Log("back")
  Close(0)
  return 1
end

function Step()
  if vrfw_co ~= nil then
    if coroutine.status(vrfw_co) == "dead" then
      vrfw_co = nil
    else
      local ok, err = coroutine.resume(vrfw_co)
      if not ok then
        PRINT("vrfw_chain_board_menu: " .. tostring(err))
        Log("error", tostring(err))
        vrfw_co = nil
        funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
      elseif coroutine.status(vrfw_co) == "dead" then
        vrfw_co = nil
      end
    end
  end
  if ready and open_guard > 0 then
    open_guard = open_guard - 1
  end
  -- Redraws when a texture came in, or when the last one finished loading.
  if ready and Kit.waiting then
    Kit.settle()
    if tex_changed or not Kit.pending() then
      tex_changed = false
      DrawAll()
    end
  end
  -- Pays chests that were opened but never paid (VRFW.chain.unpaid).
  if ready and open_guard <= 0 and vrfw_co == nil and mode == "board" and B ~= nil and pay_check ~= B then
    pay_check = B
    local rank_due = VRFW.chain.news ~= nil and (#VRFW.chain.news(B) > 0 or #VRFW.chain.rank_unpaid(B) > 0)
    if (VRFW.chain.unpaid ~= nil and #VRFW.chain.unpaid(B) > 0) or rank_due then
      StartCo(PayPending)
    end
  end
  if ready then
    PollPointer()
  end
end
